import{_ as s,k as a,a6 as i,j as t}from"./chunks/framework.W_BvR9CP.js";const u=JSON.parse('{"title":"v1.35.0-RC.1","description":"The changelog for v1.35.0-RC.1.","frontmatter":{"title":"v1.35.0-RC.1","page_title":"v1.35.0-RC.1 Changelog","description":"The changelog for v1.35.0-RC.1.","category":"Pre-Releases","mentions":["8Crafter"]},"headers":[{"level":2,"title":"Additions","slug":"additions","link":"#additions","children":[{"level":3,"title":"Blocks","slug":"blocks","link":"#blocks","children":[]},{"level":3,"title":"Chat Escape Codes","slug":"chat-escape-codes","link":"#chat-escape-codes","children":[]},{"level":3,"title":"Commands","slug":"commands","link":"#commands","children":[]},{"level":3,"title":"Mute System","slug":"mute-system","link":"#mute-system","children":[]},{"level":3,"title":"Settings","slug":"settings","link":"#settings","children":[]},{"level":3,"title":"UIs","slug":"uis","link":"#uis","children":[]},{"level":3,"title":"Ultra Security Mode","slug":"ultra-security-mode","link":"#ultra-security-mode","children":[{"level":4,"title":"Permissions","slug":"permissions","link":"#permissions","children":[]}]}]},{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[{"level":3,"title":"Commands","slug":"commands-1","link":"#commands-1","children":[]},{"level":3,"title":"Performance","slug":"performance","link":"#performance","children":[]},{"level":3,"title":"Settings","slug":"settings-1","link":"#settings-1","children":[]},{"level":3,"title":"Teleport Systems","slug":"teleport-systems","link":"#teleport-systems","children":[]},{"level":3,"title":"TPA System","slug":"tpa-system","link":"#tpa-system","children":[]},{"level":3,"title":"UIs","slug":"uis-1","link":"#uis-1","children":[]}]},{"level":2,"title":"Removals","slug":"removals","link":"#removals","children":[{"level":3,"title":"Settings","slug":"settings-2","link":"#settings-2","children":[]}]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[{"level":3,"title":"Commands","slug":"commands-2","link":"#commands-2","children":[]},{"level":3,"title":"Entities","slug":"entities","link":"#entities","children":[]},{"level":3,"title":"Settings","slug":"settings-3","link":"#settings-3","children":[]},{"level":3,"title":"UIs","slug":"uis-2","link":"#uis-2","children":[]}]},{"level":2,"title":"Technical Additions","slug":"technical-additions","link":"#technical-additions","children":[{"level":3,"title":"API","slug":"api","link":"#api","children":[{"level":4,"title":"cmdutils Module","slug":"cmdutils-module","link":"#cmdutils-module","children":[]},{"level":4,"title":"Config","slug":"config","link":"#config","children":[]},{"level":4,"title":"Globals","slug":"globals","link":"#globals","children":[]},{"level":4,"title":"Modules","slug":"modules","link":"#modules","children":[]}]},{"level":3,"title":"Permanent Event Subscriptions","slug":"permanent-event-subscriptions","link":"#permanent-event-subscriptions","children":[]}]},{"level":2,"title":"Technical Changes","slug":"technical-changes","link":"#technical-changes","children":[{"level":3,"title":"API","slug":"api-1","link":"#api-1","children":[{"level":4,"title":"cmdutils Module","slug":"cmdutils-module-1","link":"#cmdutils-module-1","children":[]},{"level":4,"title":"Config","slug":"config-1","link":"#config-1","children":[]}]}]},{"level":2,"title":"Technical Fixes","slug":"technical-fixes","link":"#technical-fixes","children":[{"level":3,"title":"Commands","slug":"commands-3","link":"#commands-3","children":[]}]}],"relativePath":"changelogs/v1.35.0-rc.1.md","filePath":"changelogs/v1.35.0-rc.1.md"}'),l={name:"changelogs/v1.35.0-rc.1.md"};function n(h,e,o,d,r,c){return t(),a("div",null,e[0]||(e[0]=[i('<p><strong>Renamed the add-on from <code class="shiki"><span>8Crafter&#39;s Debug Sticks, Chat Ranks, Custom UI, JavaScript Commands/Script REPL, and Server Utilities</span></code> to <code class="shiki"><span>8Crafter&#39;s Server Utilities &amp; Debug Sticks</span></code>!</strong></p><h2 id="additions" tabindex="-1">Additions <a class="header-anchor" href="#additions" aria-label="Permalink to &quot;Additions&quot;">​</a></h2><h3 id="blocks" tabindex="-1">Blocks <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;Blocks&quot;">​</a></h3><ul><li>Added the <a href="./../blocks/invalid-block-placeholder.html#Normal"><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">andexdb:invalid_block_placeholder</span></code></a> block.</li><li>Added the <a href="./../blocks/invalid-block-placeholder.html#No_Occlusion%2C_No_Dimming"><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">andexdb:invalid_block_placeholder_no_occlusion_no_dimming</span></code></a> block.</li><li>Added the <a href="./../blocks/invalid-block-placeholder.html#Lit"><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">andexdb:invalid_block_placeholder_lit</span></code></a> block.</li></ul><h3 id="chat-escape-codes" tabindex="-1">Chat Escape Codes <a class="header-anchor" href="#chat-escape-codes" aria-label="Permalink to &quot;Chat Escape Codes&quot;">​</a></h3><ul><li>Added the <code class="shiki"><span>${ase}</span></code> chat secape code, which is the same as <code class="shiki"><span>${se}</span></code> except that is evaluates the provided script in an asynchronous function, so <code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">system</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">run</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">()</span></code> is not needed to use functions that can&#39;t be used in read-only mode, and you can use the <code class="shiki"><span>await</span></code> keyword. And awaited promises will actually have their errors caught and logged to the chat, instead of only to the console, which you wouldn&#39;t be able to see the errors from unless you were on a dedicated server and had console access, or were on a world and you were the host. It requires the same permissions as the <code class="shiki"><span>${se}</span></code> escape code.</li></ul><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Added the <a href="./../commands-list/--loadchunks.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\loadchunks</span></code></a> command. It has one alias: <code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\lc</span></code>.</li><li>Added the <code class="shiki"><span>duration</span></code> parameter to the <a href="./../commands-list/-selectionrender.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\selectionrender</span></code></a> command.</li><li>Added the <code class="shiki"><span>t</span></code> flag to the <a href="./../commands-list/-takeitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\takeitem</span></code></a> command. This flag causes the command to create ghost items if the slot type is a number or <code class="shiki"><span>~</span></code>.</li><li>Added the <a href="./../commands-list/-tpaccept.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpaccept</span></code></a> command.</li><li>Added the <a href="./../commands-list/-tpdeny.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpdeny</span></code></a> command.</li><li>Added the <a href="./../commands-list/-gmg.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\gmg</span></code></a> command.</li><li>Added the <a href="./../commands-list/--expandselection.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\expandselection</span></code></a> command.</li><li>Added the <a href="./../commands-list/--generateterrain.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\generateterrain</span></code></a> command.</li><li>Added the <code class="shiki"><span>f</span></code> flag to the <a href="./../commands-list/--remove.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\remove</span></code></a> command. This flag causes the command to execute in fast mode, fast mode causes the command to run all in one tick and using <a href="https://learn.microsoft.com/en-us/minecraft/creator/scriptapi/minecraft/server/blockvolumebase?view=minecraft-bedrock-experimental#getblocklocationiterator" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">BlockVolumeBase</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">prototype</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">getBlockLocationIterator</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">()</span></code></a> to get all the non-air blocks in the selected area. Note: This flag will cause the command to freeze the world/realm/server until it finishes executing or triggers a script hang error.</li></ul><h3 id="mute-system" tabindex="-1">Mute System <a class="header-anchor" href="#mute-system" aria-label="Permalink to &quot;Mute System&quot;">​</a></h3><p>Added a new <a href="./../systems/mute.html">Mute System</a>!</p><p>You can mute players through the <a href="./../main-menu/moderation.html#quick-mute">Quick Mute</a> menu.</p><p>You can also mute or unmute players through the <a href="./../main-menu/manage-players.html">Manage Players</a> menu.</p><p>You can also manage mutes through the <a href="./../main-menu/moderation.html#manage-mutes">Manage Mutes</a> menu.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Added the <a href="./../settings/script.html#default-min-ms-between-tick-waits"><code class="shiki"><span>Default Min MS Between Tick Waits</span></code></a> setting (<a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.system.html#defaultminmsbetweentickwaits" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">system</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">defaultMinMsBetweenTickWaits</span></code></a>) to the <a href="./../settings/script.html">Script Settings</a> menu.</li><li>Added 4 new options related to the console and chat logs about whether or not a compatible version of the <a href="/andexdb/../main/add-ons/bluemods-anticheat.html">BlueMods Anticheat</a> add-on is on the world to the <a href="./../settings/script.html">Script Settings</a> menu.</li></ul><h3 id="uis" tabindex="-1">UIs <a class="header-anchor" href="#uis" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Huge overhaul to the <a href="./../main-menu/moderation.html">Moderation</a> menu. <ul><li>The menu now disabled the non-functional buttons.</li><li>Rearranged the buttons on the menu.</li><li>Added the <a href="./../main-menu/moderation.html#quick-actions">Quick Actions</a> submenu. <ul><li>This submenu contains buttons for quickly banning, kicking, and muting players, and even transferring players to other servers!</li></ul></li><li>Huge internal structure overhaul to improve performance and make it easier to add new features.</li></ul></li><li>Added menus for resetting player and preset permissions in Ultra Security Mode.</li></ul><h3 id="ultra-security-mode" tabindex="-1">Ultra Security Mode <a class="header-anchor" href="#ultra-security-mode" aria-label="Permalink to &quot;Ultra Security Mode&quot;">​</a></h3><h4 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h4><ul><li>Added the <code class="shiki"><span>andexdb.bypassTeleportCooldowns</span></code> permission to Ultra Security Mode.</li><li>Added the <code class="shiki"><span>andexdb.transferPlayers</span></code> permission to Ultra Security Mode.</li><li>Added the <code class="shiki"><span>andexdb.mutePlayers</span></code> permission to Ultra Security Mode.</li><li>Added the <code class="shiki"><span>andexdb.unmutePlayers</span></code> permission to Ultra Security Mode.</li><li>Added the <code class="shiki"><span>andexdb.accessManageMutesUI</span></code> permission to Ultra Security Mode.</li><li>Added the <code class="shiki"><span>andexdb.useScriptEval</span></code> permission to Ultra Security Mode.</li></ul><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><h3 id="commands-1" tabindex="-1">Commands <a class="header-anchor" href="#commands-1" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>The <a href="./../commands-list/-takeitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\takeitem</span></code></a> command now no longer creates ghost items, unless the new <code class="shiki"><span>t</span></code> flag is used and the slot type is a number or <code class="shiki"><span>~</span></code>.</li><li>The <a href="./../commands-list/-takeitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\takeitem</span></code></a> command now takes a target selector instead of a player name.</li><li>The <a href="./../commands-list/-copyitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\copyitem</span></code></a> command now takes a target selector instead of a player name.</li><li>The <a href="./../commands-list/-copyitem.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\copyitem</span></code></a> command now allows for multiple targets.</li><li>The <a href="./../commands-list/-tpa.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpa</span></code></a> command now uses the new <a href="./../systems/tpa.html">TPA system</a>.</li><li>The <a href="./../commands-list/-gmr.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\gmr</span></code></a> command now has a chance to set you to god mode (Game Mode 7).</li><li>The <a href="./../commands-list/-help.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\help</span></code></a> command now displays the URL of the page on the wiki for the command when getting the help for a built-in command.</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>Massive performance improvements to the <a href="./../systems/money.html">Money System</a>.</li></ul><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Massive overhaul to the <a href="./../settings/script.html">Script Settings</a> menu.</li><li>The <a href="./../settings/module-imports.html">Module Imports Config</a> now defaults to having everything enabled.</li></ul><h3 id="teleport-systems" tabindex="-1">Teleport Systems <a class="header-anchor" href="#teleport-systems" aria-label="Permalink to &quot;Teleport Systems&quot;">​</a></h3><ul><li>Made it so if Ultra Security Mode is enabled, players with the <code class="shiki"><span>andexdb.bypassTeleportCooldowns</span></code> permission can bypass the countdown and cooldown for teleports with things such as the homes and warps systems, and if Ultra Security Mode is disabled, then players with the <code class="shiki"><span>admin</span></code> tag can bypass it.</li></ul><h3 id="tpa-system" tabindex="-1">TPA System <a class="header-anchor" href="#tpa-system" aria-label="Permalink to &quot;TPA System&quot;">​</a></h3><ul><li>The <a href="./../systems/tpa.html">TPA system</a> is no longer experimental.</li></ul><h3 id="uis-1" tabindex="-1">UIs <a class="header-anchor" href="#uis-1" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Made the &quot;Reset Permissions&quot; button in the Security menu use the red reset icon instead of the settings icon.</li><li>Made the &quot;Ultra Security Mode Debug&quot; button in the security settings menu use the debug glyph color icon instead of the settings icon.</li><li>The <a href="./../settings/advanced/eval-auto-execute.html">Eval Auto Execute Settings</a> menu now requires the <code class="shiki"><span>andexdb.useScriptEval</span></code> and <code class="shiki"><span>andexdb.accessAdvancedSettings</span></code> permissions when Ultra Security Mode is enabled (before it only needed <code class="shiki"><span>andexdb.accessSettings</span></code>).</li><li>Depecated the <a href="./../settings/advanced/eval-auto-execute.html">Eval Auto Execute Settings</a> menu.</li><li>Added a Done button to the View Raw Data menu of the Edit Custom Area Category menu to allow players using controllers to scroll in the menu.</li></ul><h2 id="removals" tabindex="-1">Removals <a class="header-anchor" href="#removals" aria-label="Permalink to &quot;Removals&quot;">​</a></h2><h3 id="settings-2" tabindex="-1">Settings <a class="header-anchor" href="#settings-2" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Removed the <a href="./../settings/script.html#protected-areas-refresh-rate"><code class="shiki"><span>Protected Areas Refresh Rate</span></code></a> option from the <a href="./../settings/script.html">Script Settings</a> menu.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><h3 id="commands-2" tabindex="-1">Commands <a class="header-anchor" href="#commands-2" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Fixed the <a href="./../commands-list/-swapitems.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\swapitems</span></code></a> command.</li><li>Fixed the <a href="./../commands-list/-copyitemfrom.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\copyitemfrom</span></code></a> command.</li><li>Fixed the <code class="shiki"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">-</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">32768</span></code> option for the <a href="./../commands-list/-enchantmentbarrels.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\enchantmentbarrels</span></code></a> command.</li><li>Fixed a bug where the <a href="./../commands-list/--regenerateblocks.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\regenerateblocks</span></code></a> command would log <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span></code> to the console whenever it was run.</li><li>Fixed a bug where the <a href="./../commands-list/--chunk.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\chunk</span></code></a> command set the top and bottom of the selection based on the overworld height limit instead of based on the height limit of the executor&#39;s current dimension.</li><li>Fixed a bug where the <a href="./../commands-list/--chunk.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\chunk</span></code></a> command set the top of the selection 1 block above the maximum height limit.</li><li>Fixed a bug where the <a href="./../commands-list/--protectarea.html"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\protectarea</span></code></a> command would always throw an error saying that the area category was invalid, even when it was valid.</li></ul><h3 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h3><ul><li>Fixed a bug where the <a href="./../entities/tickingarea_6.html"><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">andexdb:tickingarea_6</span></code></a> entity could not be made visible if <a href="/andexdb/../main/add-ons/entity-scale.html">Entity Scale</a> was not on the world.</li></ul><h3 id="settings-3" tabindex="-1">Settings <a class="header-anchor" href="#settings-3" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>Fixed a bug where the <a href="./../settings/teleport-systems.html#allow-cross-dimensional-teleport"><code class="shiki"><span>Allow Cross-Dimensional Teleport</span></code></a> option (<a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.teleportSystems.html#allowcrossdimensionalteleport" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">teleportSystems</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">allowCrossDimensionalTeleport</span></code></a>) was labeled <code class="shiki"><span>Enabled</span></code> instead.</li></ul><h3 id="uis-2" tabindex="-1">UIs <a class="header-anchor" href="#uis-2" aria-label="Permalink to &quot;UIs&quot;">​</a></h3><ul><li>Fixed a bug where the Manage Bans menu used <a href="./../settings/ui.html#max-players-per-manage-players-page"><code class="shiki"><span>config.ui.pages.maxPlayersPerManagePlayersPage</span></code></a> instead of <a href="./../settings/ui.html#max-bans-per-manage-bans-page"><code class="shiki"><span>config.ui.pages.maxBansPerManageBansPage</span></code></a> for the number of entries per page.</li><li>Fixed a bug where the Redeem Code menu still used the old UI style.</li><li>Fixed a bug where the Bounties Placed By Me menu still used the old UI style.</li><li>Fixed a bug where the Individual Bounties menu still used the old UI style.</li><li>Fixed a bug where the Home Details menu still used the old UI style.</li><li>Fixed a bug where the New Home menu still used the old UI style.</li><li>Fixed a bug where the Individual Player Leaderboard Statistics menu still used the old UI style. (The menu that appears when you click on a player&#39;s name in the menu for a specific leaderboard.)</li><li>Fixed a bug where the Ultra Security Mode Debug menu still used the old UI style.</li><li>Fixed a bug where the Manage Permissions Presets menu still used the old UI style.</li><li>Fixed a bug where the Manage Permissions for Player/Preset menu still used the old UI style.</li><li>Fixed a bug where the Manage Permissions for Player/Preset menu had yellow labels for permissions that were enabled on the everyone preset, when editing the permissions for a preset.</li><li>Fixed a bug where the Place Bounty menu threw an error when the player had already placed a bounty on the target, now it shows a warning instead, saying that to do it, they will have to remove the previous bounty first, and it provides and option to do so.</li><li>Fixed a bug where the icon for the View Individual Bounties button was an arrow pointing left instead of right.</li><li>Fixed bugs with the player and server shop systems where some of the menus had not yet been updated to the new UI style.</li><li>Fixed a bug where the Edit Warp menu was called <code class="shiki"><span>New Warp</span></code> instead of <code class="shiki"><span>Edit Warp</span></code>.</li><li>Fixed a bug where the Warps menu was using the <code class="shiki"><span>general</span></code> form style instead of the <code class="shiki"><span>medium</span></code> form style.</li><li>Fixed a bug where the Homes menu was using the <code class="shiki"><span>general</span></code> form style instead of the <code class="shiki"><span>medium</span></code> form style.</li><li>Fixed a bug where the Leaderboards menu was using the <code class="shiki"><span>general</span></code> form style instead of the <code class="shiki"><span>medium</span></code> form style.</li><li>Fixed a bug where the Leaderboards menu could throw an error if any of the leaderboard buttons were undefined.</li><li>Fixed a bug where the scoreboard-based leaderboards did not work correctly.</li><li>Fixed a bug where the buttons for the warps in the <a href="./../settings/ui/menu-configurations/player-menu/manage-warps.html">Manage Warps</a> menu would not appear.</li><li>Fixed a bug where the <a href="./../settings/ui/menu-configurations/player-menu/leaderboards-settings/manage-statistics.html#editing-a-built-in-statistic">Edit Built-In Statistic</a> menu put you in an infinite loop when trying to use escape or the back button.</li><li>Fixed a bug where the <a href="./../settings/ui/menu-configurations/player-menu/leaderboards-settings/manage-statistics.html#editing-a-built-in-statistic">Edit Built-In Statistic</a> menu would go back to the <a href="./../settings/ui/menu-configurations/player-menu/leaderboards-settings/manage-statistics.html">Manage Statistics</a> menu and cause it to be open twice, instead of re-opening itself, upon exiting out of the Settings menu for the statistic.</li><li>Fixed a bug where the <a href="./../settings/ui/menu-configurations/player-menu/leaderboards-settings/edit-displayed-leaderboards.html">Edit Displayed Leaderboards</a> menu rendered the buttons for the leaderboards incorrectly.</li><li>Fixed a bug where the Add ID Ban and Add Name Ban buttons on the Manage Bans menu were not rendered correctly.</li><li>Fixed a bug where the Quick Ban, Quick Kick, Quick Mute, and Quick Transfer menus did not map the button indexes for the back, close, and refresh buttons correctly, causing them to behave unexpectedly.</li></ul><h2 id="technical-additions" tabindex="-1">Technical Additions <a class="header-anchor" href="#technical-additions" aria-label="Permalink to &quot;Technical Additions&quot;">​</a></h2><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><h4 id="cmdutils-module" tabindex="-1">cmdutils Module <a class="header-anchor" href="#cmdutils-module" aria-label="Permalink to &quot;cmdutils Module&quot;">​</a></h4><ul><li>Added <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.modules.cmdutils.getItemFromParsedSlot.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">cmdutils</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">getItemFromParsedSlot</span></code></a></li></ul><h4 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h4><ul><li>Added <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.system.html#defaultminmsbetweentickwaits" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">system</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">defaultMinMSBetweenTickWaits</span></code></a>.</li></ul><h4 id="globals" tabindex="-1">Globals <a class="header-anchor" href="#globals" aria-label="Permalink to &quot;Globals&quot;">​</a></h4><ul><li>Added the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.gsend.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">gsend</span></code></a> function.</li><li>Added the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.gcsend.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">gcsend</span></code></a> function.</li><li>Added the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.pgsend.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">pgsend</span></code></a> function.</li><li>Added the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.pgcsend.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">pgcsend</span></code></a> function.</li></ul><h4 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h4><ul><li>Added the <a href="https://api.8crafter.com/andexdb/v1.35.0/modules/Globals.modules.moderation.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">moderation</span></code></a> module.</li><li>Added the <a href="https://api.8crafter.com/andexdb/v1.35.0/modules/Globals.modules.alea.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">alea</span></code></a> module (Note: The module was already in the add-on, but was not in the <code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span></code> namespace.).</li><li>Added the <a href="https://api.8crafter.com/andexdb/v1.35.0/modules/Globals.modules.simplexNoise.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">simplexNoise</span></code></a> module (Note: The module was already in the add-on, but was not in the <code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span></code> namespace.).</li></ul><h3 id="permanent-event-subscriptions" tabindex="-1">Permanent Event Subscriptions <a class="header-anchor" href="#permanent-event-subscriptions" aria-label="Permalink to &quot;Permanent Event Subscriptions&quot;">​</a></h3><ul><li>Added a new permanent event subscriptions system. <ul><li>The new permanent event subscriptions system allows you to register code that will execute when an event occurs.</li><li>It supports ALL vanilla script API events, and a few custom events.</li><li>It supports the following custom events: <ul><li><a href="https://api.8crafter.com/andexdb/v1.35.0/classes/_internal_.andexdbBeforeEvents.html#modifiedchatmessageformat" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">andexdb</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">beforeEvents</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modifiedChatMessageFormat</span></code></a></li><li><a href="https://api.8crafter.com/andexdb/v1.35.0/classes/_internal_.andexdbBeforeEvents.html#modifiedchatmessageformatfinalization" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">andexdb</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">beforeEvents</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modifiedChatMessageFormatFinalization</span></code></a></li><li><a href="https://api.8crafter.com/andexdb/v1.35.0/classes/_internal_.andexdbBeforeEvents.html#modifiedchatmessagesend" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">andexdb</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">beforeEvents</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modifiedChatMessageSend</span></code></a></li><li><a href="https://api.8crafter.com/andexdb/v1.35.0/classes/_internal_.andexdbBeforeEvents.html#modifiedchatmessagesend" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">andexdb</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">afterEvents</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modifiedChatMessageSend</span></code></a></li></ul></li><li>You can create these permanent event subscriptions either through the <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.Events.html" target="_blank" rel="noreferrer">script eval</a> or the <a href="./../settings/advanced/manage-event-subscriptions.html">Manage Event Subscriptions</a> menu.</li></ul></li></ul><h2 id="technical-changes" tabindex="-1">Technical Changes <a class="header-anchor" href="#technical-changes" aria-label="Permalink to &quot;Technical Changes&quot;">​</a></h2><ul><li>When Entity Scale or BlueMods Anticheat are not detected upon startup, the add-on will now tell you in the console as a warning, rather than a log, so that you don&#39;t have to change your log level to see it.</li></ul><h3 id="api-1" tabindex="-1">API <a class="header-anchor" href="#api-1" aria-label="Permalink to &quot;API&quot;">​</a></h3><h4 id="cmdutils-module-1" tabindex="-1">cmdutils Module <a class="header-anchor" href="#cmdutils-module-1" aria-label="Permalink to &quot;cmdutils Module&quot;">​</a></h4><ul><li>Massive performance improvements to the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.modules.cmdutils.getSlotFromParsedSlot.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">cmdutils</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">getSlotFromParsedSlot</span></code></a> function.</li><li>Massive performance improvements to the <a href="https://api.8crafter.com/andexdb/v1.35.0/functions/Globals.modules.cmdutils.parseSlot.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">cmdutils</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">parseSlot</span></code></a> function.</li></ul><h4 id="config-1" tabindex="-1">Config <a class="header-anchor" href="#config-1" aria-label="Permalink to &quot;Config&quot;">​</a></h4><ul><li>Deprecated <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.config.system.html#protectedareasrefreshrate" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">config</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">system</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">protectedAreasRefreshRate</span></code></a>.</li></ul><h2 id="technical-fixes" tabindex="-1">Technical Fixes <a class="header-anchor" href="#technical-fixes" aria-label="Permalink to &quot;Technical Fixes&quot;">​</a></h2><h3 id="commands-3" tabindex="-1">Commands <a class="header-anchor" href="#commands-3" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>Fixed a bug where some of the chat commands were using <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.modules.cmds.executeCommandPlayerW.html#sendmessageb" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">executeCommandPlayerW</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">prototype</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">sendMessageB</span></code></a> to send errors instead of <a href="https://api.8crafter.com/andexdb/v1.35.0/classes/Globals.modules.cmds.executeCommandPlayerW.html#senderror" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">executeCommandPlayerW</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">prototype</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">sendError</span></code></a>.</li></ul>',67)]))}const p=s(l,[["render",n]]);export{u as __pageData,p as default};
